def repair_rowscore(g, spans, rows, bg):
 out=[r[:] for r in g]; chosen=[]
 for lo,hi,t in spans:
  cols=list(range(lo+1,hi-1));n=len(rows);cand=[]
  for p in range(1,n//2+1):
   templates=[]; badrows=0; cells=0
   for k in range(p):
    inds=list(range(k,n,p));temp=[]
    for c in cols:
     vals=[g[rows[i]][c]==t for i in inds];temp.append(sum(vals)*2>len(vals))
    templates.append(temp)
   for i in range(n):
    diff=sum((g[rows[i]][c]==t)!=templates[i%p][j] for j,c in enumerate(cols))
    badrows+=diff>0;cells+=diff
   cand.append((badrows,cells,p,templates))
  br,ce,p,temp=min(cand,key=lambda z:(z[0],z[2]));chosen.append((br,ce,p))
  for i,r in enumerate(rows):
   for j,c in enumerate(cols):out[r][c]=t if temp[i%p][j] else bg
 return out,chosen
